package com.neu.riketiku.zhishikapian;import com.neu.riketiku.renzheng.RenZhengYongHu;import jakarta.validation.Valid;import java.util.List;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/student/knowledge-cards") public class KnowledgeCardPracticeController{private final KnowledgeCardPracticeService service;public KnowledgeCardPracticeController(KnowledgeCardPracticeService service){this.service=service;}@PostMapping("/{cardId}/exercises")public List<KnowledgeCardPracticeDtos.Exercise>generate(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long cardId,@Valid@RequestBody KnowledgeCardPracticeDtos.Generate r){return service.generate(u.id(),cardId,r);}@GetMapping("/exercises/{id}")public KnowledgeCardPracticeDtos.Exercise detail(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long id){return service.detail(u.id(),id);}@PostMapping("/exercises/{id}/answer")public KnowledgeCardPracticeDtos.Exercise answer(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long id,@Valid@RequestBody KnowledgeCardPracticeDtos.Answer r){return service.answer(u.id(),id,r.answer());}@PostMapping("/exercises/{id}/submit-review")public KnowledgeCardPracticeDtos.Exercise submit(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long id){return service.submit(u.id(),id);}}
